-- entity-engine partitions: generated by `cli entities plan --write`; forward-only; immutable once on origin/main.
-- Reviewed like a hand-written migration. No transaction control.

-- create_index public.records_accounting_question:index:records_accounting_question_source: on workspace_id, data->>'source', id using btree
CREATE INDEX "records_accounting_question_source" ON public."records_accounting_question" USING btree (workspace_id, (data->>'source'), id);
-- add_check public.records_accounting_settings:constraint:records_accounting_settings_rematch_days_chk: added NOT VALID, then validated
ALTER TABLE public."records_accounting_settings" ADD CONSTRAINT "records_accounting_settings_rematch_days_chk" CHECK ((data->>'rematchDays') IS NOT NULL AND (jsonb_typeof(data->'rematchDays') = 'number' AND (data->>'rematchDays') ~ '^-?[0-9]{1,10}$')) NOT VALID;
ALTER TABLE public."records_accounting_settings" VALIDATE CONSTRAINT "records_accounting_settings_rematch_days_chk";
